import { optim } from "../optim/optim.js";
import { optimize } from "../numerics/integrate.js";
import { qnorm } from "../distributions/normal.js";
import { decompose } from "./statsTs.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const HOLT_WINTERS_KEYS = /* @__PURE__ */ new Set([
  "frequency", "alpha", "beta", "gamma", "seasonal", "startPeriods", "lStart", "bStart", "sStart",
]);
const PREDICT_HOLT_WINTERS_KEYS = ["nAhead", "predictionInterval", "level"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

/** Options of {@link holtWinters}. */
export interface HoltWintersOptions {
  frequency?: number;
  /** Given, or estimated when undefined; `false` for beta / gamma leaves that component out. */
  alpha?: number;
  beta?: number | false;
  gamma?: number | false;
  seasonal?: "additive" | "multiplicative";
  startPeriods?: number;
  lStart?: number; bStart?: number; sStart?: readonly number[];
}

/** Result of {@link holtWinters}. */
export interface HoltWintersResult {
  alpha: number; beta: number | false; gamma: number | false;
  /** a, b, s1..sf (R's coefficients). */
  coefficients: number[];
  coefficientNames: string[];
  SSE: number;
  /** One-step fitted values from the first fitted time (R's fitted xhat). */
  fitted: number[];
  /** The time index (0-based) of the first fitted value. */
  start: number;
  seasonal: "additive" | "multiplicative";
  frequency: number;
  x: number[];
}

/**
 * Holt-Winters filtering (stats' `HoltWinters()`): exponential smoothing with optional trend and seasonal components,
 * the start values from decompose() of the first start.periods periods, the parameters minimising the SSE.
 *
 * @category Time series
 */
export function holtWinters(x: readonly number[], options: HoltWintersOptions = {}): HoltWintersResult {
  checkOptions(options, HOLT_WINTERS_KEYS, "holtWinters"); // generated: option-keys.mjs
  const xs = x.map(Number); const f = options.frequency ?? 1; const n = xs.length;
  const seasonal = options.seasonal ?? "additive";
  const useGamma = options.gamma !== false && f > 1; const useBeta = options.beta !== false;
  let l0: number, b0 = 0, s0: number[] = []; let startT: number;
  if (useGamma) {
    // decompose of the first startPeriods periods; l and b = intercept and slope of lm(trend ~ 1..k) (log 12)
    const sp = options.startPeriods ?? 2;
    const d = decompose(xs.slice(0, sp * f), { frequency: f, type: seasonal });
    const tr = d.trend.filter((v) => !Number.isNaN(v)); const k = tr.length;
    const tm = (k + 1) / 2; const ym = tr.reduce((a, b) => a + b, 0) / k;
    let sxy = 0, sxx = 0; tr.forEach((v, i) => { sxy += (i + 1 - tm) * (v - ym); sxx += (i + 1 - tm) ** 2; });
    const slope = sxy / sxx;
    l0 = options.lStart ?? ym - slope * tm; b0 = options.bStart ?? slope; s0 = options.sStart ? [...options.sStart] : d.figure;
    startT = f; // the recursions from t = f + 1 (1-based)
  } else if (useBeta) { l0 = options.lStart ?? xs[1]!; b0 = options.bStart ?? xs[1]! - xs[0]!; startT = 2; }
  else { l0 = options.lStart ?? xs[0]!; startT = 1; }
  const run = (al: number, be: number, ga: number): { sse: number; level: number; trend: number; season: number[]; fitted: number[] } => {
    let level = l0, trend = useBeta ? b0 : 0; const season = s0.slice(); const fitted: number[] = []; let sse = 0;
    for (let t = startT; t < n; t++) {
      const sIdx = (t - startT) % f; const st = useGamma ? season[sIdx]! : seasonal === "multiplicative" ? 1 : 0;
      const xhat = useGamma ? (seasonal === "additive" ? level + trend + st : (level + trend) * st) : level + trend;
      fitted.push(xhat); const e = xs[t]! - xhat; sse += e * e;
      const lPrev = level;
      level = useGamma ? (seasonal === "additive" ? al * (xs[t]! - st) + (1 - al) * (level + trend) : (al * xs[t]!) / st + (1 - al) * (level + trend)) : al * xs[t]! + (1 - al) * (level + trend);
      if (useBeta) trend = be * (level - lPrev) + (1 - be) * trend;
      if (useGamma) season[sIdx] = seasonal === "additive" ? ga * (xs[t]! - level) + (1 - ga) * st : (ga * xs[t]!) / level + (1 - ga) * st;
    }
    return { sse, level, trend, season, fitted };
  };
  let al = options.alpha ?? NaN, be = useBeta ? (options.beta as number | undefined) ?? NaN : 0, ga = useGamma ? (options.gamma as number | undefined) ?? NaN : 0;
  const free: ("a" | "b" | "g")[] = [];
  if (Number.isNaN(al)) free.push("a"); if (useBeta && Number.isNaN(be)) free.push("b"); if (useGamma && Number.isNaN(ga)) free.push("g");
  if (free.length === 1) {
    const which = free[0]!;
    const r = optimize((v) => run(which === "a" ? v : al, which === "b" ? v : be, which === "g" ? v : ga).sse, 0, 1);
    if (which === "a") al = r.optimum; else if (which === "b") be = r.optimum; else ga = r.optimum;
  } else if (free.length > 1) {
    const start = free.map((k) => (k === "a" ? 0.3 : k === "b" ? 0.1 : 0.1));
    const set = (u: readonly number[]): [number, number, number] => { let a2 = al, b2 = be, g2 = ga; free.forEach((k, i) => { if (k === "a") a2 = u[i]!; else if (k === "b") b2 = u[i]!; else g2 = u[i]!; }); return [a2, b2, g2]; };
    // L-BFGS-B on [0, 1] (R's default start 0.3, 0.1, 0.1); restarted to a tight optimum
    let r = optim(start, (u) => run(...set(u)).sse, { method: "L-BFGS-B", lower: 0, upper: 1 });
    for (let k = 0; k < 5; k++) { const r2 = optim(r.par, (u) => run(...set(u)).sse, { method: "L-BFGS-B", lower: 0, upper: 1, control: { factr: 1 } }); const better = r2.value < r.value; r = better ? r2 : r; if (!better) break; }
    [al, be, ga] = set(r.par);
  }
  const fin = run(al, be, ga);
  // coefficients: a, b, s1..sf with s1 the season of the next period
  const nextIdx = (n - startT) % f;
  const seasonOut = useGamma ? Array.from({ length: f }, (_, i) => fin.season[(nextIdx + i) % f]!) : [];
  const coefficients = [fin.level, ...(useBeta ? [fin.trend] : []), ...seasonOut];
  const coefficientNames = ["a", ...(useBeta ? ["b"] : []), ...seasonOut.map((_, i) => `s${i + 1}`)];
  return { alpha: al, beta: useBeta ? be : false, gamma: useGamma ? ga : false, coefficients, coefficientNames, SSE: fin.sse, fitted: fin.fitted,
    start: startT, seasonal, frequency: f, x: xs };
}

/**
 * Predictions from a {@link holtWinters} fit with intervals (stats' `predict.HoltWinters()`): additive and
 * non-seasonal models var(residuals) (1 + sum_{j<h} psi_j^2), psi_j = alpha (1 + j beta) + gamma (1 - alpha) [j mod f
 * = 0]; multiplicative models var(residuals) sum_{j=0}^{h-1} (psi_j s_h / s_{h-j})^2 with cyclic seasonal indices
 * (R reads the seasonal factors at fixed positions of its coefficient vector instead: R bug 19369; equal for h < f with
 * a trend).
 *
 * @category Time series
 */
export function predictHoltWinters(fit: HoltWintersResult, options: { nAhead?: number; predictionInterval?: boolean; level?: number } = {}): { fit: number[]; upr?: number[]; lwr?: number[] } {
  checkOptions(options, PREDICT_HOLT_WINTERS_KEYS, "predictHoltWinters"); // generated: option-keys.mjs
  const h = options.nAhead ?? 1; const f = fit.frequency;
  const hasB = fit.beta !== false; const hasS = fit.gamma !== false;
  const a = fit.coefficients[0]!; const b = hasB ? fit.coefficients[1]! : 0; const s = hasS ? fit.coefficients.slice(hasB ? 2 : 1) : [];
  const sAt = (k: number): number => s[(k - 1) % f]!; // k = 1..: the season of horizon k
  const pred = Array.from({ length: h }, (_, i) => {
    const k = i + 1; const base = a + k * b;
    return !hasS ? base : fit.seasonal === "additive" ? base + sAt(k) : base * sAt(k);
  });
  if (!options.predictionInterval) return { fit: pred };
  const res = fit.x.slice(fit.start).map((v, i) => v - fit.fitted[i]!);
  const mean = res.reduce((p, q) => p + q, 0) / res.length; const v = res.reduce((p, q) => p + (q - mean) ** 2, 0) / (res.length - 1);
  const al = fit.alpha, be = hasB ? (fit.beta as number) : 0, ga = hasS ? (fit.gamma as number) : 0;
  const psi = (j: number): number => al * (1 + j * be) + (hasS && j % f === 0 ? ga * (1 - al) : 0);
  const q = qnorm(0.5 + (options.level ?? 0.95) / 2);
  const half = pred.map((_, i) => {
    const k = i + 1;
    if (!hasS || fit.seasonal === "additive") { let acc = 1; for (let j = 1; j < k; j++) acc += psi(j) ** 2; return q * Math.sqrt(v * acc); }
    let acc = 0; for (let j = 0; j < k; j++) acc += ((psi(j) * sAt(k)) / sAt(k - j === 0 ? f : k - j)) ** 2;
    return q * Math.sqrt(v * acc);
  });
  return { fit: pred, upr: pred.map((p, i) => p + half[i]!), lwr: pred.map((p, i) => p - half[i]!) };
}
